"""Guard the independent DFS node identities generated by the smoke driver."""
from __future__ import annotations

import importlib.util
from pathlib import Path
import tempfile
import unittest
from unittest import mock

SCRIPT = Path(__file__).with_name('three_node_core.py')
spec = importlib.util.spec_from_file_location('dfs_three_node_core', SCRIPT)
module = importlib.util.module_from_spec(spec)
assert spec.loader is not None
spec.loader.exec_module(module)
REPO = SCRIPT.resolve().parents[5]


class ThreeNodeConfigTests(unittest.TestCase):
    def test_node_c_has_distinct_paths_and_preserves_peer_certificates(self):
        owner = module.load_owner_helpers(REPO)
        with tempfile.TemporaryDirectory() as temp:
            root = Path(temp).resolve()
            scenario = module.DfsCoreRun(owner, REPO, root / 'bin', root)
            with mock.patch.object(scenario.run, 'command', return_value=''):
                scenario.run.write_configs()
                scenario._rewrite_configs()
            b = (root / 'etc/node-b.toml').read_text()
            c = (root / 'etc/node-c.toml').read_text()
            self.assertIn('id = "node-c"', c)
            self.assertIn('grpc_listen = "127.0.0.4:', c)
            self.assertIn(f'data_dir = "{root}/node-c/state"', c)
            self.assertIn(f'dfs_mount = "{root}/node-c/mount/dfs"', c)
            self.assertNotIn('ownerfs_mount =', c)
            self.assertIn('fs = "dfs"', c)
            trusted_b = next(line for line in b.splitlines() if line.startswith('trusted_node_certs ='))
            trusted_c = next(line for line in c.splitlines() if line.startswith('trusted_node_certs ='))
            self.assertEqual(trusted_b, trusted_c)
            for node in ('node-a', 'node-b', 'node-c'):
                self.assertIn(f'{node} = "{root}/tls/{node}.pem"', trusted_c)


if __name__ == '__main__':
    unittest.main()
